mapper.select:
SELECT EXISTS (
    SELECT 1 FROM PRTNR_MST
     WHERE ACTV_BRNO = #{brno}
)

mapper.insert:
INSERT INTO PRTNR_MST (
    USER_SN, CONM, BRNO, RPRSV_NM, ADDR, DADDR, MAIL_ORDER_SALES_NO, PIC_NM, PIC_MBL_TELNO, PRTNR_EML_ADDR,
    APRV_STTS, REG_DT, MDFCN_DT, RGTR_SN
) VALUES (
    #{userSn}, #{conm}, #{brno}, #{rprsvNm}, #{addr}, #{daddr}, #{mailOrderSalesNo}, #{picNm},
    #{picMblTelno, typeHandler=egovframework.eeum.base.crypto.PicMblTelnoEncryptedTypeHandler}, #{prtnrEmlAddr},
    'REQUESTED', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{userSn}
)

INSERT INTO PARTNER_APPROVE_LOG_INFO (
    PRTNR_SN, BFR_APRV_STTS, AFT_APRV_STTS, RSN, ACTR_USER_SN, REG_DT
) VALUES (
    #{prtnrSn}, #{bfrAprvStts}, #{aftAprvStts}, #{rsn}, #{actrUserSn}, UTC_TIMESTAMP(6)
)

mapper.update:
UPDATE PRTNR_MST
CONM = #{conm}, BRNO = #{brno}, RPRSV_NM = #{rprsvNm}, ADDR = #{addr}, DADDR = #{daddr}, MAIL_ORDER_SALES_NO = #{mailOrderSalesNo}, PIC_MBL_TELNO = #{picMblTelno, typeHandler=egovframework.eeum.base.crypto.PicMblTelnoEncryptedTypeHandler}, PIC_NM = #{picNm}, PRTNR_EML_ADDR = #{prtnrEmlAddr}, BRNO_VRFC_STTS = 'REQUESTED', MDFCN_DT = UTC_TIMESTAMP(6), MDFR_SN = #{mdfrSn}
WHERE PRTNR_SN = #{prtnrSn} AND DEL_YN = 'N'
